// Binary search: returns index or FONT_NORNS_EXT_N_CHARS if not found
inline int FontNornsExtLookup(uint16_t cp) {
    int lo = 0, hi = FONT_NORNS_EXT_N_CHARS - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (font_norns_ext_codepoints[mid] < cp) lo = mid + 1;
        else if (font_norns_ext_codepoints[mid] > cp) hi = mid - 1;
        else return mid;
    }
    return FONT_NORNS_EXT_N_CHARS;
}

